import itertools

# Define prices and target totals
prices = [0.50, 3.00, 10.50]
total_cost = 50.00
total_items = 100

# Function to validate a combination
def is_valid_combination(counts):
    return (
        sum(count * price for count, price in zip(counts, prices)) == total_cost and
        sum(counts) == total_items
    )

# Iterate over possible combinations
for x in range(1, int(total_items / len(prices)) + 1):
    for y in range(1, int((total_items - x) / (len(prices) - 1)) + 1):
        z = total_items - x - y
        # Check if we have at least one of each type
        if x > 0 and y > 0 and z > 0:
            # Validate the current combination
            if is_valid_combination([x, y, z]):
                print(f'Success! Found valid combination: {x} items @ ${prices[0]}, {y} items @ ${prices[1]}, {z} items @ ${prices[2]}')
                break
else:
    print('No valid combination found.')

